import styled from '@emotion/styled';
import { theme } from 'theme';

interface StyledGanttChartWithMilestonesProps {
  $weekDelimiter?: boolean;
}

export const StyledGanttChartWithMilestones = styled.div<StyledGanttChartWithMilestonesProps>(
  ({ $weekDelimiter }) => ({
    flex: 1,
    minHeight: '36px',
    display: 'flex',
    alignItems: 'center',
    borderRight: '1px solid #14141414',
    ...($weekDelimiter && {
      borderRight: `1px solid ${theme.colors.charts.border.neutrals[40]}`,
    }),
    '.tooltip-trigger': {
      width: '100%',
    },
  }),
);

type MilestoneTiming = 'start' | 'end' | 'unique';

interface StyledGanttChartWithMilestonesCellProps {
  $activeWeek?: boolean;
  $timing?: MilestoneTiming;
}

export const StyledGanttChartWithMilestonesCell = styled.div<StyledGanttChartWithMilestonesCellProps>(
  ({ $activeWeek, $timing }) => ({
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    width: '100%',
    minHeight: '15px',
    ...($activeWeek && {
      borderTop: '1px solid #14141414',
      borderBottom: '1px solid #14141414',
    }),
    ...($timing === 'start' && {
      borderLeft: '1px solid #14141414',
      borderRadius: '16px 0 0 16px',
    }),
    ...($timing === 'end' && {
      borderRight: '1px solid #14141414',
      borderRadius: '0 16px 16px 0',
    }),
    ...($timing === 'unique' && {
      border: '1px solid #14141414',
      borderRadius: '50%',
    }),
  }),
);

export const StyledMilestone = styled.span({
  width: '8px',
  height: '8px',
  borderRadius: '50%',
});
